// ================== Internal Update Functions ================
public(package) fun onboard_new_asset<MarketType, CoinType>(
    self: &mut Market<MarketType>,
    interest_model: InterestModel,
    borrow: AssetConfig,
    now: u64,
    ctx: &mut TxContext,
) {
    assert!(!self.assets.supports<Asset<MarketType>, CoinType>(), error::asset_already_onboarded());

    let new_asset = asset::new<MarketType>(interest_model, borrow, ctx);
    self.assets.store<Asset<MarketType>, CoinType>(new_asset);

    let reserve = reserve::new<MarketType, CoinType>(ctx, now);
    self.reserves.store<Reserve<MarketType>, CoinType>(reserve);

    self.ema_spot_tolerance.store<Decimal, CoinType>(float::from_quotient(DEFAULT_EMA_SPOT_DIFF_TOLERANCE_BPS, DEFAULT_EMA_SPOT_DIFF_DENOMINATOR));

    self.liquidity_miner.support_coin<MarketType, CoinType>(ctx);
}

public(package) fun handle_new_obligation<MarketType>(
    self: &mut Market<MarketType>,
    obligation: Obligation<MarketType>,
) {
    self.obligations.add(object::id(&obligation), obligation);
}

public(package) fun borrow_liquidity_mining<MarketType>(self: &Market<MarketType>): &LiquidityMiner<MarketType> {
    &self.liquidity_miner
}

public(package) fun borrow_liquidity_mining_mut<MarketType>(self: &mut Market<MarketType>): &mut LiquidityMiner<MarketType> {
    &mut self.liquidity_miner
}

public(package) fun handle_mint<MarketType, CoinType>(
    self: &mut Market<MarketType>,
    obligation: ID,
    coin: Coin<CoinType>,
    now: u64,
): (u64, u64) {
    assert!(coin.value() != 0, error::no_zero_amount());

    let name = type_name::with_defining_ids<CoinType>();
    let deposit_amount = coin.value();

    let asset = self.assets.load_mut_by_type(name);
    assert!(!asset.deposit_paused(), error::deposit_paused_for_asset());

    let asset_config = asset.asset_config();

    let reserve = accrue_interest<MarketType>(name, &mut self.reserves, asset_config, asset.interest_model(), now);

    // technically should be in stable coin value, but keep it this way for now
    assert!(
        !reserve.deposit_limit_breached<MarketType>(
            deposit_amount,
            asset_config.max_deposit_amount(),
        ),
        error::market_deposit_limit_exceeded(),
    );

    let ctoken = reserve.mint_ctokens(coin);
    let ctoken_amount = ctoken.value();

    // now handle obligation related
    let obligation = self.obligations.borrow_mut(obligation);
    assert!(
        obligation.market_id() == self.id.uid_as_inner(),
        error::obligation_from_different_market(),
    );
    obligation.deposit_ctoken<MarketType, CoinType>(ctoken);

    // update rate limit deposit 
    let emode = self.emode_group_registry.borrow_mut_emode(obligation.emode_group(), type_name::with_defining_ids<CoinType>());
    emode.borrow_mut_deposit_limiter().reduce_outflow(now, deposit_amount);

